import os
import json
from typing import Any, Dict, List, Optional

from openai import OpenAI

STANDARD_EXPENSE_SCHEMA = {
    "merchant_name": None,
    "transaction_date": None,
    "currency": None,
    "subtotal": None,
    "tax": None,
    "tip": None,
    "total": None,
    "payment_method": None,
    "invoice_number": None,
    "receipt_number": None,
    "category": None,
    "line_items": [],
    "raw_text": None,
}


def _strip_code_fences(text: str) -> str:
    text = text.strip()
    if text.startswith("```"):
        lines = text.splitlines()
        if len(lines) >= 2:
            lines = lines[1:]
        if lines and lines[-1].strip() == "```":
            lines = lines[:-1]
        text = "\n".join(lines).strip()
    return text


def _normalize_line_items(items: Any) -> List[Dict[str, Any]]:
    if not isinstance(items, list):
        return []

    normalized = []
    for item in items:
        if not isinstance(item, dict):
            continue
        normalized.append(
            {
                "description": item.get("description"),
                "quantity": item.get("quantity"),
                "unit_price": item.get("unit_price"),
                "total_price": item.get("total_price"),
                "category": item.get("category"),
            }
        )
    return normalized


def _merge_with_schema(data: Dict[str, Any], raw_text: Optional[str]) -> Dict[str, Any]:
    result = dict(STANDARD_EXPENSE_SCHEMA)
    for key in result:
        if key == "line_items":
            result[key] = _normalize_line_items(data.get("line_items"))
        elif key == "raw_text":
            result[key] = data.get("raw_text", raw_text)
        else:
            result[key] = data.get(key)
    return result


def normalize_expense_fields(extracted_fields: Dict[str, Any], raw_text: Optional[str] = None) -> Dict[str, Any]:
    api_key = os.environ["OPENAI_API_KEY"]
    client = OpenAI(api_key=api_key)

    prompt = {
        "task": "Normalize extracted expense fields into the target JSON schema.",
        "requirements": [
            "Return valid JSON only.",
            "Use null for missing scalar values.",
            "Use an empty array for missing line_items.",
            "Keep currency as a 3-letter ISO code when possible.",
            "Normalize transaction_date to YYYY-MM-DD when possible.",
            "Do not invent values that are not supported by the input.",
        ],
        "target_schema": {
            "merchant_name": "string|null",
            "transaction_date": "string|null",
            "currency": "string|null",
            "subtotal": "number|null",
            "tax": "number|null",
            "tip": "number|null",
            "total": "number|null",
            "payment_method": "string|null",
            "invoice_number": "string|null",
            "receipt_number": "string|null",
            "category": "string|null",
            "line_items": [
                {
                    "description": "string|null",
                    "quantity": "number|null",
                    "unit_price": "number|null",
                    "total_price": "number|null",
                    "category": "string|null",
                }
            ],
            "raw_text": "string|null",
        },
        "input": {
            "extracted_fields": extracted_fields,
            "raw_text": raw_text,
        },
    }

    response = client.responses.create(
        model="gpt-4.1-mini",
        input=[
            {
                "role": "system",
                "content": (
                    "You normalize OCR or extracted expense data into a strict JSON schema. "
                    "Respond with JSON only and no additional commentary."
                ),
            },
            {
                "role": "user",
                "content": json.dumps(prompt, ensure_ascii=False),
            },
        ],
    )

    content = response.output_text
    parsed = json.loads(_strip_code_fences(content))
    return _merge_with_schema(parsed, raw_text)
